39:     const data: any[] = [];
40:     let index = 0;
41:     for (const aspirante of this.aspirantes) {
42:       const persona: any = await this.consultarTercero(aspirante.PersonaId)
43:       const detallesEvaluacion: any = await this.consultarDetalleEvaluacion(aspirante.Id);
44:       const detalleIcfes = detallesEvaluacion.filter((item: any) => item.RequisitoProgramaAcademicoId.RequisitoId.CodigoAbreviacion === "ICFES")
45: 
46:       if (detallesEvaluacion === "No existe data") {
47:         continue;
48:       }
49:       
50:       const pregrado: any = await this.consultarInscripcionPregrado(aspirante.Id)
51: 
52:       if (detalleIcfes.length > 0) {
53:         let jsonObjectDataIcfes = JSON.parse(detalleIcfes[0].DetalleCalificacion);
54:         const item = {
55:           n: index + 1,
56:           credencial: "No disponible",
57:           nombre: `${persona.PrimerNombre} ${persona.SegundoNombre}`,
58:           apellido: `${persona.PrimerApellido} ${persona.SegundoApellido}`,
59:           documento: persona.NumeroIdentificacion,
60:           snp: pregrado[0].CodigoIcfes,
61:           icfes: jsonObjectDataIcfes.global ? jsonObjectDataIcfes.global : jsonObjectDataIcfes.GLOBAL,
62:           ponderado: aspirante.NotaFinal,
63:           inscripcion: aspirante.TipoInscripcionId.Nombre,
64:           estado: aspirante.EstadoInscripcionId.Nombre
65:         }
66:         data.push(item);
67:       }
68:       index ++;
69:     }
70:     this.datasourceInscritos = new MatTableDataSource(data);
71:     this.datasourceInscritos.paginator = this.paginator1;
72:   }
